      var metadata = JSON.parse(metadataStr);
      
      // Clear old data and write new
      sheetOnline.clear();
      sheetOnline.appendRow(['File ID', 'Status', 'Kategori', 'Judul', 'Waktu Ditambahkan', 'Penulis', 'Penerbit', 'Tahun', 'Stok', 'Lokasi', 'URL Cover']);
